text:
{
  "units": [
    {
      "issue": {
        "id": "U0",
        "role": "main",
        "topic": "截至2023-08-01，在SP-01到账后，乙对A、B、C的剩余清偿范围，以及丁、戊、庚、己各自是否负有立即付款义务和相应责任范围"
      },
      "decisive_facts": [
        "全部案件事实为显著标明的虚构题设，不存在可供提取的真实法院裁判结论。",
        "结算不计2023-08-01当日利息；最终余额必须反映当日已经到账的SP-01。",
        "最终请求分别涉及A财产返还、B可保护本息、C本金及合法利息和费用；不请求保证合同无效后的过错赔偿。",
        "S06另明确将庚列入最终付款请求对象，应与S12合并读取。",
        "各输出分项最终取分后相加；保证人对同一债务的责任不能另行累计为乙的新增债务。"
      ],
      "support_spans": [
        {
          "kind": "material",
          "spans": ["normalized_text首段", "S06", "S12", "S13"],
          "anchors": [
            "不是真实诉讼、证据或判决",
            "甲将庚也列为最终付款请求对象",
            "不请求计算保证合同无效后的过错赔偿",
            "最终诉请所核对的是本回单到账后的剩余余额"
          ]
        }
      ],
      "dependencies": [
        {
          "from": "U1",
          "to": "U0",
          "relation": "确定A返还余额及丁的保证合同付款请求边界"
        },
        {
          "from": "U2",
          "to": "U8",
          "relation": "提供SP-01前B的合法余额、金额构成及适用利率"
        },
        {
          "from": "U3",
          "to": "U4",
          "relation": "提供去重后的C实际付款及逐笔抵充约定"
        },
        {
          "from": "U4",
          "to": "U8",
          "relation": "提供SP-01前C的合法余额、金额构成及付款日适用利率"
        },
        {
          "from": "U5",
          "to": "U6",
          "relation": "分别确定对戊、庚行权的效果，再判断是否发生内部追偿损失减免"
        },
        {
          "from": "U6",
          "to": "U8",
          "relation": "提供B在付款日的担保覆盖状态"
        },
        {
          "from": "U7",
          "to": "U8",
          "relation": "提供C在付款日的担保存续状态，不以先诉抗辩替代担保消灭判断"
        },
        {
          "from": "U8",
          "to": "U0",
          "relation": "确定SP-01后的B、C余额，并与各保证人的责任状态合并"
        }
      ],
      "answerability": {
        "status": "supported_for_P1",
        "basis": "主问题所需的交付、计息、抵充、保证及程序事件均有题设定位和所附规范支持。",
        "pending": "最终金额、保证责任金额上限及汇总值须在P4建立参考，并经独立复算；本阶段不生成问题或最终答案。"
      }
    },
    {
      "issue": {
        "id": "U1",
        "role": "dependency",
        "topic": "A的效力、无效后返还范围与丁的从属性保证责任"
      },
      "decisive_facts": [
        "A于2022-03-11签订，资金系甲套取的银行消费信贷资金，来源已由题设确认。",
        "乙事先不知资金来源、约定利率为6%，但这两项事实不能替代对适用版本无效要件的核对。",
        "票面为160000元，实际交付143021.00元；乙此前返还20169.00元。",
        "双方仅在A被认定无效的条件下约定此前付款全部抵充返还财产，不请求其他无效后赔偿。",
        "另份收据与到账记录具有同一银行交易号；丁为A提供保证，题设排除了其他法律例外。"
      ],
      "support_spans": [
        {
          "kind": "material",
          "spans": ["S01", "S02", "S12"],
          "anchors": [
            "甲把为个人消费用途向银行套取的信贷资金转给乙",
            "如A被认定无效，双方同意在清算中全部作为已返还财产冲抵",
            "其银行交易号与S01到账记录一致"
          ]
        },
        {
          "kind": "rule",
          "source_id": "lending-2020-12",
          "provisions": ["13", "31"],
          "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html"
        },
        {
          "kind": "rule",
          "source_id": "civil-code-2020",
          "provisions": ["157", "682"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html"
        }
      ],
      "dependencies": [
        {
          "from": "A成立时间及资金来源",
          "to": "A效力状态",
          "relation": "按适用的2020年12月修正规则审查，不加入2015年版本的高利转贷及借款人知情条件"
        },
        {
          "from": "A效力状态",
          "to": "A财产返还范围",
          "relation": "触发S02附条件清算约定，以实际交付扣除已返还财产"
        },
        {
          "from": "A效力状态",
          "to": "丁的保证合同效力及付款请求边界",
          "relation": "适用保证从属性，并排除题设未请求的无效保证过错赔偿"
        }
      ],
      "answerability": {
        "status": "supported_for_P1",
        "basis": "支持提取主合同无效后的财产返还与保证从属性判断；不支持把未交付票面差额、同交易号收据或未请求的赔偿加入金额。"
      }
    },
    {
      "issue": {
        "id": "U2",
        "role": "dependency",
        "topic": "B的实际本金、逐次合法结息、整体本息上限及SP-01前余额"
      },
      "decisive_facts": [
        "B于2022-01-12实际到账184810.00元并成立、起息；票面197187.00元中的12377.00元系预扣利息。",
        "约定年利率13.200%，合同成立时一年期LPR为题设确定的3.70%。",
        "2022-07-06、2022-10-17、2023-01-09三次归档均无新增交付。",
        "双方同意结息记账、不另成立债务更新合同，各期沿用原利率及原合同成立时LPR。",
        "按实际自然日及365年基数计算，保留中间精度；B没有其他还款。",
        "B原到期日为2023-01-12，甲乙展期至2023-06-30；截至结算日已到期。"
      ],
      "support_spans": [
        {
          "kind": "material",
          "spans": ["S03", "S04", "S05", "S06", "S12", "S13"],
          "anchors": [
            "乙于2022-01-12实际收到184810.00元",
            "各归档日的新增银行转账均为0元",
            "双方不另成立债务更新合同",
            "保留全部计算精度，仅在最终各输出金额上四舍五入到分"
          ]
        },
        {
          "kind": "rule",
          "source_id": "civil-code-2020",
          "provisions": ["670", "679", "680"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html"
        },
        {
          "kind": "rule",
          "source_id": "lending-2020-12",
          "provisions": ["25", "26", "27", "28"],
          "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html"
        }
      ],
      "dependencies": [
        {
          "from": "实际交付与预扣记录",
          "to": "B起始本金",
          "relation": "以实际出借额确定本金，不能直接采用票面金额"
        },
        {
          "from": "B起始本金、结息约定及归档日期",
          "to": "逐次可保护的结息本金",
          "relation": "按约定13.20%计息并审查法定限额，不能把14.80%的保护上限当成约定利率或直接接受纸面本金"
        },
        {
          "from": "逐次合法结息结果",
          "to": "B截日前候选本息",
          "relation": "继续计算末次结息后的合法利息，并核对到期及逾期阶段"
        },
        {
          "from": "B截日前候选本息及原始本金",
          "to": "B的SP-01前可保护余额",
          "relation": "另行比较第27条整体本息上限；该比较不能替代逐次结息审查"
        }
      ],
      "answerability": {
        "status": "supported_for_P1",
        "basis": "交付、成立、起息、结息、展期和截止日期已明确，能够建立可复算参考。",
        "pending": "逐段日数、合法结息金额、独立整体上限及最终采用值尚未复算，不预判哪一项数值上限实际起约束作用。"
      }
    },
    {
      "issue": {
        "id": "U3",
        "role": "dependency",
        "topic": "C付款记录的执行状态、交易去重及逐笔抵充约定"
      },
      "decisive_facts": [
        "T-01至T-07均有已结算记录，且均指定清偿C债务。",
        "银行截图及甲收据中的T-01与主表首行交易号相同。",
        "X-01仅提交过付款指令，银行明确未执行、已撤销且未入甲账户。",
        "原合同约定费用、依法可请求利息、本金的抵充顺序。",
        "2019-08-23双方补充协议仅对T-02约定本金优先，其余依次为费用和利息。",
        "其他付款的“还本金”备注仅为乙单方记载，甲未同意。"
      ],
      "support_spans": [
        {
          "kind": "material",
          "spans": ["S08", "S09", "S11"],
          "anchors": [
            "两份记录的银行交易号均与S08首行相同",
            "X-01未执行，已撤销付款指令，未向甲账户记入该金额",
            "仅适用于T-02的补充协议",
            "甲未在这些备注上签字，也未以其他方式同意"
          ]
        },
        {
          "kind": "rule",
          "source_id": "civil-code-2020",
          "provisions": ["561"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html",
          "scope": "用于施行后的抵充规则核对；2019年的抵充顺序直接依据题设明确的双方协议，不溯及适用本条。"
        }
      ],
      "dependencies": [
        {
          "from": "交易号及银行执行结果",
          "to": "C实际付款清单",
          "relation": "同一T-01只计一次；未执行X-01不作为清偿"
        },
        {
          "from": "双方原合同、T-02补充协议及单方备注",
          "to": "逐笔抵充顺序",
          "relation": "区分有效的双方例外约定与未获同意的单方付款备注"
        },
        {
          "from": "C实际付款清单及逐笔抵充顺序",
          "to": "U4",
          "relation": "确定各付款日对费用、利息、本金的实际减少额"
        }
      ],
      "answerability": {
        "status": "supported_for_P1",
        "basis": "银行执行状态与双方约定均为明确题设；乙关于点击提交即完成付款的说法仅为单方主张，不能替代到账记录。"
      }
    },
    {
      "issue": {
        "id": "U4",
        "role": "dependency",
        "topic": "C旧借款的利率过渡、分时清偿与SP-01前本金及合法利息余额"
      },
      "decisive_facts": [
        "C于2019-02-07实际交付225330.00元、成立并起息，无预扣利息。",
        "借期及逾期约定年利率均为23.50%；2022年的保证文件不构成新借款或债务更新。",
        "案件于2023-08-01新受理；C各次起诉受理时一年期LPR均由题设确定为3.25%。",
        "甲明确请求成立日至2020-08-19按当时司法解释计算，其后仅请求法律保护范围内利息。",
        "费用1680元于2019-04-17已经发生并到期，题设确认依法可收取。",
        "按未清偿本金、实际自然日/365单利计算；付款当日不再对已偿本金计息，未付利息不另计息。"
      ],
      "support_spans": [
        {
          "kind": "material",
          "spans": ["normalized_text首段", "S07", "S08", "S09", "S10", "S12"],
          "anchors": [
            "2022年保证文件不构成另起借款合同或债务更新",
            "甲明确请求按照合同成立至2020-08-19当时的司法解释计算该段利息",
            "每次付款当日不对被偿还本金继续计息",
            "未付利息不另计息"
          ]
        },
        {
          "kind": "rule",
          "source_id": "lending-2015",
          "provisions": ["26"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/15146.html"
        },
        {
          "kind": "rule",
          "source_id": "lending-2020-12",
          "provisions": ["25", "28", "31"],
          "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html"
        }
      ],
      "dependencies": [
        {
          "from": "C成立时间、新受理时间及甲的分段请求",
          "to": "C合法利率时间轴",
          "relation": "2020-08-19以前核对23.50%与旧24%标准；2020-08-20起按题设起诉时LPR四倍即13.00%核对"
        },
        {
          "from": "U3",
          "to": "逐次付款后的费用、利息、本金状态",
          "relation": "按照各笔适用的抵充顺序更新余额，T-02的本金优先会改变后续计息基数"
        },
        {
          "from": "合法利率时间轴及逐次付款余额",
          "to": "C的SP-01前余额",
          "relation": "在2020-08-20及实际付款日分段，保持本金、未付利息和费用分账"
        }
      ],
      "answerability": {
        "status": "supported_for_P1",
        "basis": "旧借款与新保证成立时间能够区分，过渡条款所需的请求及报价事实齐全。",
        "pending": "须独立复算各段日数与付款归属，不得只用名义23.50%贯穿全程，也不得从2019年起统一改按13.00%。"
      }
    },
    {
      "issue": {
        "id": "U5",
        "role": "dependency",
        "topic": "B保证类型、未同意展期的期间效果，以及对戊、庚分别行权的效力"
      },
      "decisive_facts": [
        "戊的正文约定乙不履行到期债务时即无条件清偿，无须甲先向乙追索；两份独立合同均明确各自对外覆盖全部B债务。",
        "两人的保证期间均写为直至B本息全部还清；均未书面同意展期。",
        "B原到期日为2023-01-12，甲乙后来展期至2023-06-30。",
        "针对戊的诉讼于2023-07-05有效受理，完整给付诉状于2023-07-07送达，2023-07-09撤诉。",
        "甲对庚首次主张于2023-07-18到达；此前未向庚主张、起诉或仲裁，也未向庚送达针对戊的诉状。",
        "撤诉不包含和解、清偿或放弃实体债权。"
      ],
      "support_spans": [
        {
          "kind": "material",
          "spans": ["S06"],
          "anchors": [
            "无须甲先向乙追索",
            "戊未书面同意展期",
            "起诉状副本2023-07-07实际送达戊",
            "甲仅在2023-07-18首次向庚催告并到达"
          ]
        },
        {
          "kind": "rule",
          "source_id": "civil-code-2020",
          "provisions": ["688", "692", "693", "695"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html"
        },
        {
          "kind": "rule",
          "source_id": "guarantee-2020",
          "provisions": ["25", "29", "31", "32", "34"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/282721.html"
        }
      ],
      "dependencies": [
        {
          "from": "保证正文",
          "to": "B保证类型",
          "relation": "按责任触发条件识别连带责任保证，不依标题是否出现类型名称"
        },
        {
          "from": "原到期日、期间条款及未书面同意展期",
          "to": "B保证期间边界",
          "relation": "以原履行期限核对六个月期间，不能随借款双方展期重新起算"
        },
        {
          "from": "B保证期间边界及戊的送达、撤诉事件",
          "to": "对戊依法行权的状态",
          "relation": "适用连带保证撤诉但诉状已经送达的规则"
        },
        {
          "from": "B保证期间边界及庚的首次催告",
          "to": "对庚依法行权的状态",
          "relation": "独立核对是否及时，不能把对戊行权扩张为对庚行权"
        }
      ],
      "answerability": {
        "status": "supported_for_P1",
        "basis": "材料支持区分戊的期间内有效行权与庚的期间外首次催告；保证期间不因撤诉、催告或未经同意的展期而自动重启。"
      }
    },
    {
      "issue": {
        "id": "U6",
        "role": "dependency",
        "topic": "庚退出保证责任是否使戊因丧失内部追偿而减责，以及B剩余担保覆盖范围"
      },
      "decisive_facts": [
        "戊、庚分别在独立合同签署，不是在同一份合同书上共同签署，也不是同一合同的分拆页。",
        "二人没有相互追偿、分担份额或连带共同担保约定。",
        "各自对甲覆盖全部B债务的连带责任，仅指各保证人与乙的外部责任。",
        "戊主张因甲未及时向庚行权而免除相应责任；该主张本身不是既定法律结论。",
        "保证范围明确包含原B关系按法定限额清算的本息及依法允许的结息部分。",
        "题设认可保证人在依法存续范围内的履行能力与价值，无其他影响内部追偿的事由。"
      ],
      "support_spans": [
        {
          "kind": "material",
          "spans": ["S06"],
          "anchors": [
            "两份为各自独立的合同，不是同一合同的分拆页",
            "戊庚之间未约定相互追偿或分担份额",
            "不是对甲各担一半",
            "范围包括原B关系按法定限额清算的全部本息及依法允许的结息部分"
          ]
        },
        {
          "kind": "rule",
          "source_id": "guarantee-2020",
          "provisions": ["13", "29"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/282721.html"
        },
        {
          "kind": "rule",
          "source_id": "civil-code-2020",
          "provisions": ["688", "691", "695"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html"
        }
      ],
      "dependencies": [
        {
          "from": "独立签约及无内部追偿约定",
          "to": "戊对庚的内部追偿基础",
          "relation": "按第13条分别核对约定追偿、连带共同担保和同一合同共同签署条件"
        },
        {
          "from": "U5及内部追偿基础",
          "to": "戊的追偿损失减免主张",
          "relation": "第29条减免以原本存在相互追偿权为前提，不能仅因有两名保证人即减半"
